import re


def snake_to_camel(word):
    """Write a function to convert the given snake case string to camel case string by using regex."""
    s = re.sub(r'_+([A-Za-z0-9])', lambda m: m.group(1).upper(), word)
    s = re.sub(r'_', '', s)
    if not s:
        return s
    return s[0].upper() + s[1:]
